package run.ikaros.password; import java.security.SecureRandom; import java.util.ArrayList; import java.util.Collections; import java.util.List; import org.springframework.stereotype.Service; import reactor.core.publisher.Mono; @Service public class PasswordGeneratorService{private static final String U="ABCDEFGHIJKLMNOPQRSTUVWXYZ",L="abcdefghijklmnopqrstuvwxyz",N="0123456789",S="!@#$%^&*()-_=+[]{}:,.?";private static final String[] WORDS={"amber"," cedar","cobalt","dawn","ember","fjord","harbor","jade","lantern","maple","orbit","pine","quartz","river","solar","tiger","violet","willow"};private final SecureRandom random=new SecureRandom();public Mono<GeneratedSecretView> password(PasswordGenerateRequest q){int length=q.length()==null?20:Math.max(8,Math.min(q.length(),256));StringBuilder pool=new StringBuilder();if(Boolean.TRUE.equals(q.uppercase()))pool.append(U);if(Boolean.TRUE.equals(q.lowercase())||pool.isEmpty())pool.append(L);if(Boolean.TRUE.equals(q.numbers()))pool.append(N);if(Boolean.TRUE.equals(q.symbols()))pool.append(S);if(Boolean.TRUE.equals(q.avoidAmbiguous()))for(char c:new char[]{'O','0','I','l','1','|','S','5'}){int i=pool.indexOf(String.valueOf(c));if(i>=0)pool.deleteCharAt(i);}if(pool.isEmpty())return Mono.error(new IllegalArgumentException("至少选择一种字符类型"));List<Character> out=new ArrayList<>();add(out,pool.toString(),q.minimumNumbers()==null?0:q.minimumNumbers(),N,q.avoidAmbiguous());add(out,pool.toString(),q.minimumSymbols()==null?0:q.minimumSymbols(),S,q.avoidAmbiguous());while(out.size()<length)out.add(pool.charAt(random.nextInt(pool.length())));Collections.shuffle(out,random);StringBuilder result=new StringBuilder();out.forEach(result::append);return Mono.just(new GeneratedSecretView(result.toString(),"PASSWORD"));}public Mono<GeneratedSecretView> passphrase(PassphraseGenerateRequest q){int count=q.wordCount()==null?5:Math.max(3,Math.min(q.wordCount(),20));String separator=q.separator()==null?"-":q.separator();StringBuilder result=new StringBuilder();for(int i=0;i<count;i++){if(i>0)result.append(separator);String word=WORDS[random.nextInt(WORDS.length)].trim();if(Boolean.TRUE.equals(q.capitalize()))word=Character.toUpperCase(word.charAt(0))+word.substring(1);result.append(word);}if(Boolean.TRUE.equals(q.numberSuffix()))result.append(random.nextInt(10));return Mono.just(new GeneratedSecretView(result.toString(),"PASSPHRASE"));}private void add(List<Character> out,String pool,int count,String required,Boolean avoid){for(int i=0;i<count;i++){char c;do{c=required.charAt(random.nextInt(required.length()));}while(Boolean.TRUE.equals(avoid)&&"O0Il1|S5".indexOf(c)>=0);if(pool.indexOf(c)>=0)out.add(c);}}}
